import {fontFamilies} from './font-catalog.js';
import {clone} from './model.js';
import {applyTextStyle,clearTextStyle,editText,validateText} from './text-engine.js';
import {assertCanEdit} from './layer-policy.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openTypeStudio(api){const l=api.layer();if(l?.type!=='text')throw Error('Chọn lớp chữ.');assertCanEdit(api.doc(),[l],'pixels');const original=clone(l),states=[clone(l)],dirty=new Set();let index=0,sync=()=>{};const save=()=>{validateText(l);const v=clone(l);if(JSON.stringify(v)===JSON.stringify(states[index]))return;states.splice(index+1);states.push(v);if(states.length>40)states.shift();index=states.length-1;api.requestRender();},restore=n=>{if(n<0||n>=states.length)return;index=n;for(const k of Object.keys(l))delete l[k];Object.assign(l,clone(states[n]));document.querySelector('#type-content').value=l.text;sync();api.requestRender();};
 const fields={font:['Font','select',fontFamilies(api.doc(),l.font)],fontSize:['Size','number',1,2048],fontWeight:['Weight','select',[100,200,300,400,500,600,700,800,900]],color:['Màu','color'],italic:['Nghiêng','checkbox'],underline:['Gạch dưới','checkbox'],strikethrough:['Gạch ngang','checkbox'],baselineShift:['Baseline','number',-2048,2048],tracking:['Tracking','number',-100,500],horizontalScale:['Ngang %','number',10,500],verticalScale:['Dọc %','number',10,500]},defaults={font:'Arial',fontSize:48,fontWeight:400,color:'#ffffff',italic:false,underline:false,strikethrough:false,baselineShift:0,tracking:0,horizontalScale:100,verticalScale:100};
 api.showModal('Type Studio','Định dạng từng đoạn chữ · xem trước trực tiếp · Undo trong phiên',`<div class="type-studio-grid"><div><label class="modal-field">Nội dung<textarea id="type-content" rows="10" spellcheck="false">${esc(l.text)}</textarea></label><div class="type-range-row"><label>Từ<input id="type-from" type="number" min="0" value="0"></label><label>Đến<input id="type-to" type="number" min="0" value="${l.text.length}"></label><button id="type-all" class="button">Chọn tất cả</button></div><p id="type-range-status" class="dock-caption"></p><div class="type-history"><button class="button" id="type-undo">↶ Undo</button><button class="button" id="type-redo">↷ Redo</button><small>Ctrl Z / Ctrl Shift Z</small></div></div><div><h3>Kiểu cho vùng đã chọn</h3><div class="type-field-grid">${Object.entries(fields).map(([k,[name,t,...rest]])=>`<label class="modal-field">${name}${t==='select'?`<select id="type-${k}">${[...new Set(rest[0])].map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`:`<input id="type-${k}" type="${t}" ${t==='number'?`min="${rest[0]}" max="${rest[1]}"`:''}>`}</label>`).join('')}</div><button class="button primary" id="type-apply-range">Áp kiểu vào đoạn</button><button class="button" id="type-clear-range">Xóa kiểu đoạn</button></div></div>`,[{label:'Hủy',run:()=>api.closeModal(true)},{label:'Lưu định dạng',primary:true,run:()=>{assertCanEdit(api.doc(),[l],'pixels');validateText(l);api.closeModal();api.commit('Edit rich typography');}}],()=>{const root=document.querySelector('#modal-content'),$=s=>root.querySelector(s),text=$('#type-content'),selection=()=>[Number($('#type-from').value)||0,Number($('#type-to').value)||0];sync=()=>{const [from,to]=selection(),s={...defaults,...l,...l.textRuns?.find(r=>r.from<=from&&r.to>from)?.style};dirty.clear();for(const k of Object.keys(fields)){const el=$('#type-'+k);if(el.type==='checkbox')el.checked=!!s[k];else el.value=s[k];}$('#type-range-status').textContent='Chỉ thông số bạn thay đổi được áp; giữ nguyên các kiểu khác.';$('#type-undo').disabled=index===0;$('#type-redo').disabled=index===states.length-1;};for(const k of Object.keys(fields)){$('#type-'+k).oninput=()=>dirty.add(k);$('#type-'+k).onchange=()=>dirty.add(k);}const range=()=>{if(text.selectionEnd>text.selectionStart){const change=Number($('#type-from').value)!==text.selectionStart||Number($('#type-to').value)!==text.selectionEnd;$('#type-from').value=text.selectionStart;$('#type-to').value=text.selectionEnd;if(change)sync();}};text.onselect=range;text.onmouseup=range;text.onkeyup=range;text.oninput=()=>{editText(l,text.value);save();};$('#type-from').onchange=sync;$('#type-to').onchange=sync;$('#type-all').onclick=()=>{$('#type-from').value=0;$('#type-to').value=l.text.length;text.focus();text.setSelectionRange?.(0,l.text.length);sync();};$('#type-apply-range').onclick=()=>{try{if(!dirty.size)return;const style={};for(const k of dirty){const el=$('#type-'+k);style[k]=el.type==='checkbox'?!!el.checked:['font','color'].includes(k)?el.value:Number(el.value);}applyTextStyle(l,...selection(),style);save();sync();}catch(e){api.toast(e.message,true);}};$('#type-clear-range').onclick=()=>{clearTextStyle(l,...selection());save();sync();};$('#type-undo').onclick=()=>restore(index-1);$('#type-redo').onclick=()=>restore(index+1);root.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.stopPropagation();restore(index+(e.shiftKey?1:-1));}});sync();},()=>{for(const k of Object.keys(l))delete l[k];Object.assign(l,original);api.renderUI();api.requestRender();});}
